"""Read-only M5B root cause and preregistered M5C kinematic/topology audit."""
from pathlib import Path
import sys,json,math,hashlib,re,numpy as np
from scipy.sparse import coo_matrix
from scipy.sparse.csgraph import connected_components
from pd_clot.lammps_fragmentation.macro_lab_v1 import geometry,DELTA
sys.path.insert(0,str(Path(__file__).parents[1]/'shear_boundary_notch_v2'))
