def save(p,d):p.write_text(json.dumps(d,indent=2,ensure_ascii=False,default=lambda x:x.tolist() if isinstance(x,np.ndarray) else x.item() if isinstance(x,np.generic) else x,allow_nan=False))
def js(p):return json.loads(p.read_text())
def input_groups(p,g):
 text=p.read_text();groups={m[0]:np.array(list(map(int,m[1].split())))-1 for m in re.findall(r'^group (\w+) id (.*)$',text,re.M)};coverage=np.zeros(len(g['X']),int);mask=np.zeros_like(g['X'],bool);sign=np.zeros_like(g['X'])
 for f in re.findall(r'^fix integrate\d+ (\w+) (.*)$',text,re.M):
  ids=groups[f[0]];coverage[ids]+=1;spec=f[1].split()
  if spec==['nve']:continue
  assert spec[:2]==['move','variable'];uv,vv=spec[2:5],spec[5:8]
  for d in range(3):
   if uv[d]=='NULL':assert vv[d]=='NULL';continue
   mask[ids,d]=True;var=uv[d][2:];vvar=vv[d][2:];coef=re.search(r'^variable '+re.escape(var)+r' equal ([^*]+)\*v_disp$',text,re.M);vc=re.search(r'^variable '+re.escape(vvar)+r' equal ([^*]+)\*v_vel$',text,re.M);assert coef and vc and float(coef[1])==float(vc[1]);sign[ids,d]=float(coef[1])
 assert np.all(coverage==1);assert np.array_equal(mask,g['prescribed_mask']);assert np.allclose(sign,g['prescribed_sign'],rtol=0,atol=0)
 return dict(groups=len(groups),all_nodes_integrated_exactly_once=True,prescribed_xyz=mask.sum(0),fully_prescribed_nodes=int(mask.all(1).sum()),partially_prescribed_nodes=int(mask.any(1).sum()),fully_free_nodes=int((~mask.any(1)).sum()))
def kinematics(X,b,mask,sign):
 r=np.linalg.norm(X[b[:,1]]-X[b[:,0]],axis=1);pp=mask[b,2].all(1);pn=mask[b,2].sum(1);dz=X[b[:,1],2]-X[b[:,0],2];ds=sign[b[:,1],2]-sign[b[:,0],2];zmax=np.maximum(abs(dz),abs(dz+.00068*ds));lb=zmax/r-1
 proxy=np.sqrt(r*r-dz*dz+zmax*zmax)/r-1;guaranteed=pp&(lb>=.15);fully=mask[b].all((1,2));vertical=pp&(abs(abs(dz)-r)<1e-12);return dict(pp=pp,one=pn==1,none=pn==0,fully=fully,reference_length_m=r,prescribed_axial_lower_bound_max_s=lb,reference_transverse_proxy_max_s=proxy,guaranteed=guaranteed,vertical=vertical)
def main(base,old):
 g=dict(np.load(old/'M5B/geometry.npz'));X=g['X'];b=g['bonds'];groups=input_groups(old/'M5B/in.lammps',g);fresh,cut=geometry(50e-6,'M5');assert np.array_equal(X,fresh['X']) and np.array_equal(b,fresh['bonds']);assert np.array_equal(cut,g['removed_notch_bonds']);assert len(np.unique(b,axis=0))==len(b);assert np.all(b[:,0]<b[:,1]);degree=np.bincount(b.ravel(),minlength=len(X));assert np.all(degree>0)
 # Validate actual data file against NPZ identity, not only the builder.
 text=(old/'M5B/body.data').read_text();atoms=np.array([list(map(float,l.split())) for l in text.split('Atoms # bond')[1].split('Bonds')[0].strip().splitlines() if l.strip()]);bb=np.array([list(map(int,l.split())) for l in text.split('\nBonds\n')[1].strip().splitlines() if l.strip()]);assert np.array_equal(atoms[:,0].astype(int),np.arange(1,len(X)+1));assert np.allclose(atoms[:,3:6],X,atol=1e-18,rtol=0);assert np.array_equal(bb[:,2:]-1,b);assert np.all(bb[:,1]==1)
 mask=np.zeros_like(X,bool);mask[np.isclose(abs(X[:,2]),.000475,rtol=0,atol=1e-12),2]=True;sign=np.zeros_like(X);sign[mask[:,2],2]=np.sign(X[mask[:,2],2])*.5;new=kinematics(X,b,mask,sign);before=kinematics(X,b,g['prescribed_mask'],g['prescribed_sign']);assert not new['guaranteed'].any();assert np.all(abs(new['reference_transverse_proxy_max_s'][new['pp']])<1e-12);assert not np.any(new['pp']&(X[b[:,0],2]*X[b[:,1],2]<0))
 ev=np.load(old/'M5B/break_events.npz')['events'];bt=np.full(len(b),np.inf);bt[ev[:,1]]=ev[:,0]*.5e-6;H=.00085;threshold=math.acos(1-2*.15*H/.00068)*.024/math.pi
 stats={}
 for name,k in [('M5B',before),('M5C',new)]:
  stats[name]=dict(fully_prescribed_pairs=int(k['fully'].sum()),both_axial_prescribed_pairs=int(k['pp'].sum()),one_axial_prescribed_pairs=int(k['one'].sum()),fully_free_endpoint_pairs=int(k['none'].sum()),same_axial_profile_pairs=int(np.sum(k['pp']&(abs((g['prescribed_sign'] if name=='M5B' else sign)[b[:,1],2]-(g['prescribed_sign'] if name=='M5B' else sign)[b[:,0],2])<1e-12))),guaranteed_failure_pairs=int(k['guaranteed'].sum()),vertical_both_axial_prescribed_pairs=int(k['vertical'].sum()),reference_transverse_proxy_max_s=float(k['reference_transverse_proxy_max_s'][k['pp']].max()),scope='Only z prescribed; xy remain dynamic. No fully prescribed 3D bond trajectory exists. Proxy holds xy at reference for visualization only; rigorous guarantee uses axial separation lower bound.')
 stats['M5B'].update(actual_dual_prescribed_broken=int(np.sum(before['pp']&np.isfinite(bt))),guaranteed_subset_actual_broken=int(np.sum(before['guaranteed']&np.isfinite(bt))),vertical_first_break_s=float(bt[before['vertical']].min()),vertical_last_break_s=float(bt[before['vertical']].max()),threshold_s=threshold)
 np.savez_compressed(base/'KINEMATIC_BOND_SOURCE.npz',X=X,bonds=b,types=g['bond_types'],old_mask=g['prescribed_mask'],old_sign=g['prescribed_sign'],new_mask=mask,new_sign=sign,actual_M5B_break_time_s=bt,**{'M5B_'+k:v for k,v in before.items()},**{'M5C_'+k:v for k,v in new.items()})
 # No invented exact snapshot at the mathematical threshold; record available neighbors.
 states={}
 for filename in ['pre_first_break.npz','first_break.npz','peak.npz','frame_012000.npz','frame_014000.npz','end.npz']:
  z=np.load(old/'M5B'/filename);states[filename]=dict(step=int(z['step']),time_s=float(z['time_s']),broken=int((~z['alive'].astype(bool)).sum()))
 audit=dict(input_groups=groups,kinematics=stats,initial_topology=dict(nodes=len(X),bonds=len(b),removed_notch_bonds=len(cut),min_degree=int(degree.min()),max_degree=int(degree.max()),exact_same_geometry_and_precrack=True,unexpected_cross_notch_bonds=0,illegal_duplicate_or_isolated=False),M5B_available_states=states,missing='No full coordinate snapshot exactly at6.842375ms; native event times and scalar history available at every actual step; use actual6ms/7ms fields without interpolation.',new_motion_valid=True,old_free_DOF_interpretation='Confirmed correct: fix move NULL/NULL transverse components receive force-based velocity Verlet; no fully frozen material points.')
 save(base/'GRIP_KINEMATIC_AUDIT.json',audit)
 freeze=dict(case='M5C',selected_scheme='Only outermost z=±475µm material planes prescribed axially ±disp(t)/2; all xy and all interior xyz dynamical',reason='Removes differential prescribed axial motion within each driven end plane without new material, interface, mass or contact parameters; potential mechanical corner concentration remains a hypothesis tested by the sole case',materials=dict(G_Pa=940,K_Pa=100000/3,rho_kg_m3=1000,s00_bulk=.15,s00_interface=.140624859375,alpha=0,dx_m=50e-6,horizon_m=150.5e-6,contact_distance_factor=1,damping_s_inv=500,dt_s=.5e-6),prescribed_atom_ids=(np.flatnonzero(mask[:,2])+1),fully_free_atom_ids=(np.flatnonzero(~mask.any(1))+1),prescribed_nodes=int(mask.any(1).sum()),fully_free_nodes=int((~mask.any(1)).sum()),fully_prescribed_nodes=0,free_DOF_count=int((~mask).sum()),node_count=len(X),bulk_bond_count=len(b),initial_notch_deleted_bonds=len(cut),kinematic_classification=stats['M5C'],reference_driven_plane_distance_m=.00095,old_mean_collar_distance_m=.00085,opening_amplitude_m=.00068,max_nominal_strain=.00068/.00095,loading='disp(t)=680um*0.5*(1-cos(pi*t/24ms)); derivative imposed consistently; same generalized mean opening as M5B, not same maximum-plane opening',comparison='Mean actually prescribed boundary opening; M5B outermost-plane gap increments were950/850*disp. H and plane locations explicitly differ; do not equate nominal constitutive curves.',max_duration_s=.024,max_steps=48000,region_definition=js(old/'ANALYSIS_PLAN.json'),additional_frozen_metrics=dict(crossing_bins='V2 z=0 reference intersection raster; 8 x12 bins50um; cumulative fully lost prefix from x=-100um independently per y strip; never physical area by itself',central_thickness='Four y strips [-100,100]um; central node/bond region |y|<=100um. Surface initiation |y|>=200um.',coherent_cluster='V2 six-neighbor connected dx-sized broken-midpoint voxels; >=10 occupied voxels; earliest native event, no rendered surface',substantial_central_advance='At least2 central thickness strips with contiguous crossing-loss prefix>=2dx=100um; report all12 individual advances',plane_geometry='PCA of largest connected broken-midpoint voxel cluster: normal, RMS thickness, yz coverage and secondary clusters; not automatically a physical free surface',area_gate='Unique connected tip-origin sheet, all4 central strips advance>=2dx, at least8/12 thickness strips with such advance, targetband>=70%, grip<=20%, RMS thickness<=dx, secondary clusters<10% voxels, plus independently bounded physical surface reconstruction error. A crossing-only proxy cannot certify area.'),stop_checks=dict(interval_steps=100,interval_s=50e-6,rule_order=['nonfinite/lost atoms/callback failure','max actual step displacement/dx>0.2','severe grip contamination','loss of single target-band interpretation','sustained post-separation low-load window','max24ms'],severe_grip='broken>=1000 AND V2 grip-region fraction>=0.5',loss_of_single_band='broken>=1000 AND target-band fraction<0.5 AND off-z0-plane fraction>0.6',post_separation='Two largest connected components each>=20%N and together>=80%N, top tensile reaction below10% historical positive peak (peak>50Pa*A0), sustained1ms at100-step checkpoints. Stops observation, not declares unique area.',temporal_policy='Only current accepted checkpoint state; no future data; after trigger no more blocks. Complete all preceding data; no retrospective stop adjustment.',numerical_fail='Nonfinite, lost atoms or duplicate/skipped callback steps invalidate implementation; no fabricated successful end state'),saving=dict(scalar='Every accepted step inherited full precision',native_events='Every native topology change',fields='Initial; exact pre-first and first; tensile peak; every1000steps=0.5ms; first substantial central advance; first major separation; exact termination',extra_audit='Every20steps or topology change; recurrence checks every step; native end-of-block free velocity/position checks'),budget=dict(formal_cases=1,bug_retest_max=1,no_other_cases=True),preflight='One native run0 plus static topology and kinematic checks; no nontrivial trial trajectory')
 save(base/'M5C_DESIGN_FREEZE.json',freeze)
 (base/'M5B_KINEMATIC_ROOT_CAUSE.md').write_text(f'''# M5B 规定运动的运动学根因\n\n这是正式M5C之前的只读诊断；真实来源为 `{old}/M5B`。\n\nM5B有{groups['partially_prescribed_nodes']}个材料点仅z受规定，2016个点xyz完全自由；xyz全部被规定的节点为0。锁定 `fix_move.cpp` 的VARIABLE分支对NULL/NULL分量执行半步速度和位置更新，`final_integrate`补足半步；组互斥，没有重复nve。旧报告的自由度说明正确，没有修改历史报告。\n\n两端z均受规定的键有{stats['M5B']['both_axial_prescribed_pairs']}条，三维长度不全由规定轨迹确定，因为xy仍自由。令参考轴向差ΔZ、参考长度r0，规定轴向差为 `(1+disp/H)ΔZ`，故实际伸长满足 `s >= |(1+disp/H)ΔZ|/r0 -1`。竖直键{stats['M5B']['vertical_both_axial_prescribed_pairs']}条的下界即disp/H，超过0.15后无论横向如何变化均达到断裂条件；门槛{threshold*1e3:.9f}ms。到计划末位移时，下界保证失效的键为{stats['M5B']['guaranteed_failure_pairs']}条。真实事件中该集合断裂{stats['M5B']['guaranteed_subset_actual_broken']}条；两端轴向受规定的所有键最终断裂{stats['M5B']['actual_dual_prescribed_broken']}条。\n\n图1将展示实际点阵、轴向受控键、规定轴向分离导致的严谨伸长下界，以及仅供示意的固定横向参考轨迹伸长。不可把后者称为实际三维强制轨迹。6.842375ms附近没有旧全场，使用6和7ms真实接受态及逐步事件，不插值制造快照。\n\n原边界在5.23ms优先启动缺口，但后期装置对材料夹持层直接施加拉伸，与自由裂纹耗能混合。全时程17.655581nJ是带符号拓扑项，不能除以假设裂面得到Gc。\n\n候选M5C仅规定两个最外端面的z，其他分量动力学积分。两端轴向均受规定的{stats['M5C']['both_axial_prescribed_pairs']}条键全在同一端面，规定Δz恒为0，固定横向参考轨迹的最大伸长为0；没有跨越两个相反运动端面的键。其真实横向伸长未知且由力学响应决定，因此只认证消除了必然轴向拉断，不保证夹具附近不会自然破坏。新端面参考距离950µm；保持680µm、24ms的实际端面均值开度函数，不调整名义应变去隐藏几何差异。\n\n[运动学数据](GRIP_KINEMATIC_AUDIT.json) · [冻结设计与停止规则](M5C_DESIGN_FREEZE.json)\n''')
 print(json.dumps(dict(groups=groups,kinematics=stats,M5C_nodes=freeze['prescribed_nodes'],M5C_free=freeze['fully_free_nodes']),default=lambda v:v.tolist() if isinstance(v,np.ndarray) else v,indent=2))
